pub const JSBundler = struct {

pub fn build(globalThis: *jsc.JSGlobalObject, arguments: []const jsc.JSValue) bun.JSError!jsc.JSValue {
            if (((arguments.len == 0) or (!arguments[0].isObject()))) {
                return globalThis.throwInvalidArguments("Expected a config object to be passed to Bun.build", .{});
            }
            const vm = globalThis.bunVM();
            if (vm.macro_mode) {
                return globalThis.throw("Bun.build cannot be called from within a macro during bundling.\n\nThis would cause a deadlock because the bundler is waiting for the macro to complete,\nbut the macro's Bun.build call is waiting for the bundler.\n\nTo bundle code at compile time in a macro, use Bun.spawnSync to invoke the CLI:\n  const result = Bun.spawnSync([\"bun\", \"build\", entrypoint, \"--format=esm\"]);", .{});
            }
            var plugins: ?*BundlerPlugin = null;
            _ = &plugins;
            const config = try BundlerConfig.fromJS(globalThis, arguments[0], (&plugins), bun.default_allocator);
            return bun.BundleV2.generateFromJavaScript(config, plugins, globalThis, vm.eventLoop(), bun.default_allocator);
    }

pub fn buildFn(globalThis: *jsc.JSGlobalObject, callframe: *jsc.CallFrame) bun.JSError!jsc.JSValue {
            const arguments = callframe.arguments_old(1);
            return build(globalThis, arguments.slice());
    }
